"""Self-contained private HTML view; no public API route or account write."""

from __future__ import annotations

import json
from pathlib import Path
import shutil


def write_review_page(payload: dict, target: Path, echarts_js: Path) -> Path:
    if not echarts_js.is_file():
        raise FileNotFoundError(f"本地 ECharts 资源缺失: {echarts_js}")
    target.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(echarts_js, target / "echarts.min.js")
    data = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), default=str)
    # JSON is embedded in a script element; prevent a broker name or headline
    # from closing the element and injecting arbitrary JavaScript.
    data = data.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    html = HTML.replace("__REVIEW_DATA__", data)
    page = target / "index.html"
    page.write_text(html, encoding="utf-8")
    return page


